use kobo_web_document::{box_tree::BoxTree, css_background::paint_backgrounds, display_list::Command, parse_style_tree, Limits};
fn main() { for p in std::env::args().skip(1) { let html=std::fs::read(&p).unwrap(); let t=BoxTree::from_style(&parse_style_tree(&html,&[],&Limits::DEFAULT)); print!("{}:", p.rsplit('/').next().unwrap()); match paint_backgrounds(&t,600,200){Err(e)=>println!("ERR"),Ok(l)=>{ for c in l.commands(){ if let Command::Fill{rect,color,..}=c{print!(" ({},{},{},{},{:02x}{:02x}{:02x})",rect.x,rect.y,rect.width,rect.height,color.0,color.1,color.2);} } println!();}}}}
